 "content": "import json, sys

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The frame color is the color appearing as complete horizontal and vertical lines.
    frame = next((c for c in range(10) if any(all(x == c for x in row) for row in grid)), None)
    if frame is None:
        return [row[:] for row in grid]
    rowcuts = [r for r,row in enumerate(grid) if all(x == frame for x in row)]
    colcuts = [c for c in range(w) if all(grid[r][c] == frame for r in range(h))]
    rb = [-1] + rowcuts + [h]
    cb = [-1] + colcuts + [w]
    rseg = [(rb[i]+1, rb[i+1]) for i in range(len(rb)-1)]
    cseg = [(cb[i]+1, cb[i+1]) for i in range(len(cb)-1)]
    nr,nc=len(rseg),len(cseg)
    out=[row[:] for row in grid]
    # Tile masks keyed by non-background color, in local coordinates.
    tiles={}
    for i,(r0,r1) in enumerate(rseg):
      for j,(c0,c1) in enumerate(cseg):
        d={}
        for r in range(r0,r1):
          for c in range(c0,c1):
            v=grid[r][c]
            if v != 0 and v != frame:
              d.setdefault(v,set()).add((r-r0,c-c0))
        tiles[i,j]=d
    # Within each 2x2 tile block, complete three matching reflected copies.
    for i in range(nr-1):
      for j in range(nc-1):
        for color in range(10):
          occupied=[(a,b) for a,b in ((0,0),(0,1),(1,0),(1,1)) if color in tiles[i+a,j+b]]
          if len(occupied)!=3: continue
          # Convert each observed mask back to the common top-left orientation.
          candidates=[]
          for a,b in occupied:
            mask=tiles[i+a,j+b][color]
            hh,ww=rseg[i+a][1]-rseg[i+a][0],cseg[j+b][1]-cseg[j+b][0]
            # All four tiles in a block should have matching dimensions.
            if any(rseg[i+x][1]-rseg[i+x][0] != hh for x in (0,1)) or any(cseg[j+y][1]-cseg[j+y][0] != ww for y in (0,1)):
              candidates=[]; break
            if b: mask={(r,ww-1-c) for r,c in mask}
            if a: mask={(hh-1-r,c) for r,c in mask}
            candidates.append(mask)
          if not candidates or any(x != candidates[0] for x in candidates[1:]): continue
          base=candidates[0]
          missing=next((a,b) for a,b in ((0,0),(0,1),(1,0),(1,1)) if (a,b) not in occupied)
          a,b=missing
          hh,ww=rseg[i+a][1]-rseg[i+a][0],cseg[j+b][1]-cseg[j+b][0]
          mask={(hh-1-r if a else r, ww-1-c if b else c) for r,c in base}
          r0,c0=rseg[i+a][0],cseg[j+b][0]
          for r,c in mask:
            if 0 <= r < hh and 0 <= c < ww:
              out[r0+r][c0+c]=color
    return out

if __name__ == '__main__':
    print(json.dumps(transform(json.load(sys.stdin))))
